import { z } from 'zod';
import { createOrganizationRequestSchema } from './admin';
import { officerInChargeSchema, systemRoleSchema } from './auth';
import { documentStatusSchema } from './document-status';
import { documentVisibilitySchema, scanStatusSchema } from './document';
import { organizationTypeSchema, slugSchema } from './organization';
import { systemAuditEntrySchema } from './system';

/*
 * /system accounts (docs/DOMAIN_RULES.md, "Accounts"): the super admin creates and looks
 * after the one shared account of each organization. Temporary passwords are generated by
 * the server and never shown to the super admin, except the ISSC account's own: the others go
 * to the ISSC account's one-time Reveal (reveal.ts).
 */

/** What an account list can be filtered by. `must_change`: still on a temporary password. */
export const ACCOUNT_STATUSES = ['active', 'locked', 'deactivated', 'must_change'] as const;
export const accountStatusSchema = z.enum(ACCOUNT_STATUSES);
export type AccountStatus = z.infer<typeof accountStatusSchema>;

/** Last sign-in: never, within 7 or 30 days, or longer ago. */
export const LAST_LOGIN_FILTERS = ['never', '7d', '30d', 'older'] as const;
export const lastLoginFilterSchema = z.enum(LAST_LOGIN_FILTERS);
export type LastLoginFilter = z.infer<typeof lastLoginFilterSchema>;

/** Super admins only: authenticator confirmed, or still pending. */
export const MFA_FILTERS = ['enabled', 'pending'] as const;

export const SYSTEM_USERS_PAGE_SIZE = 25;

/** GET /system/users: numbered pages, newest first. `q` matches name, email or acronym. */
export const systemUserListQuerySchema = z.object({
  q: z.string().trim().max(120).optional(),
  role: systemRoleSchema.optional(),
  type: organizationTypeSchema.optional(),
  college: slugSchema.optional(),
  organization: slugSchema.optional(),
  status: accountStatusSchema.optional(),
  lastLogin: lastLoginFilterSchema.optional(),
  mfa: z.enum(MFA_FILTERS).optional(),
  page: z.coerce.number().int().min(1).max(10_000).default(1),
  pageSize: z.coerce.number().int().min(1).max(50).default(SYSTEM_USERS_PAGE_SIZE),
});
export type SystemUserListQuery = z.input<typeof systemUserListQuerySchema>;

export const systemUserSchema = z
  .object({
    id: z.uuid(),
    name: z.string(),
    email: z.email(),
    systemRole: systemRoleSchema,
    /** Super admins only: when they confirmed their authenticator; null while pending. */
    mfaEnabledAt: z.iso.datetime().nullable(),
    disabledAt: z.iso.datetime().nullable(),
    lockedAt: z.iso.datetime().nullable(),
    lockReason: z.string().nullable(),
    /** Still on a temporary password: the next sign-in must change it. */
    mustChangePassword: z.boolean(),
    lastLoginAt: z.iso.datetime().nullable(),
    /** The organization this shared account belongs to; null for a super admin. */
    organization: z
      .object({
        slug: z.string(),
        acronym: z.string(),
        name: z.string(),
        type: organizationTypeSchema,
        /** The college code (CEA…); null for the ISSC. */
        college: z.string().nullable(),
      })
      .nullable(),
    officerInCharge: officerInChargeSchema.nullable(),
    createdAt: z.iso.datetime(),
  })
  .meta({ id: 'SystemUser' });
export type SystemUser = z.infer<typeof systemUserSchema>;

export const systemUserListResponseSchema = z
  .object({
    items: z.array(systemUserSchema),
    total: z.number().int().min(0),
    page: z.number().int().min(1),
    pageSize: z.number().int().min(1),
  })
  .meta({ id: 'SystemUserListResponse' });
export type SystemUserListResponse = z.infer<typeof systemUserListResponseSchema>;

/** GET /system/users/:userId */
export const systemUserDetailSchema = z
  .object({
    account: systemUserSchema,
    /** Officer terms, newest first. */
    terms: z.array(
      z.object({
        officerName: z.string(),
        officerPosition: z.string(),
        officerEmail: z.email(),
        termStart: z.iso.date(),
        termEnd: z.iso.date().nullable(),
        endedAt: z.iso.datetime().nullable(),
      }),
    ),
    /** The latest sign-ins and failed attempts. */
    logins: z.array(
      z.object({
        at: z.iso.datetime(),
        succeeded: z.boolean(),
        ip: z.string().nullable(),
        userAgent: z.string().nullable(),
      }),
    ),
    /** Refresh sessions still usable. */
    sessions: z.array(
      z.object({
        id: z.uuid(),
        startedAt: z.iso.datetime(),
        expiresAt: z.iso.datetime(),
        ip: z.string().nullable(),
      }),
    ),
    /** What this account did, and what was done to it, newest first. */
    audit: z.array(systemAuditEntrySchema),
  })
  .meta({ id: 'SystemUserDetail' });
export type SystemUserDetail = z.infer<typeof systemUserDetailSchema>;

const personNameSchema = z.string().trim().min(2, 'Enter a name').max(120);

/** The officer in charge of an account, as the console enters it. */
export const officerInChargeInputSchema = z.strictObject({
  name: personNameSchema,
  position: z.string().trim().min(2, 'Enter a position').max(80),
  email: z.email('Enter a valid email').trim().toLowerCase(),
});
export type OfficerInChargeInput = z.infer<typeof officerInChargeInputSchema>;

/** An account's sign-in email. The server may also limit its domain (ACCOUNT_EMAIL_DOMAINS). */
export const accountEmailSchema = z.email('Enter a valid email').trim().toLowerCase();

/** An existing organization without an account, or a new CSC or SBO made with it. */
export const accountOrganizationInputSchema = z.discriminatedUnion('kind', [
  z.strictObject({ kind: z.literal('existing'), slug: slugSchema }),
  createOrganizationRequestSchema.extend({ kind: z.literal('new') }),
]);
export type AccountOrganizationInput = z.infer<typeof accountOrganizationInputSchema>;

/** POST /system/accounts */
export const createAccountRequestSchema = z.strictObject({
  organization: accountOrganizationInputSchema,
  email: accountEmailSchema,
  officerInCharge: officerInChargeInputSchema,
  /** The planned last day of this officer term, if known. */
  termEnd: z.iso.date().nullable().optional(),
  /** The ISSC's account request this fulfils; it must be open and for this organization. */
  requestId: z.uuid().optional(),
});
export type CreateAccountRequest = z.infer<typeof createAccountRequestSchema>;

/**
 * Where a new temporary password went: the ISSC account's one-time Reveal, or (for the ISSC
 * account itself) this one response, shown once and never stored.
 */
export const passwordDeliverySchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('reveal'), expiresAt: z.iso.datetime() }),
  z.object({ kind: z.literal('shown_once'), temporaryPassword: z.string() }),
]);
export type PasswordDelivery = z.infer<typeof passwordDeliverySchema>;

export const createAccountResponseSchema = z
  .object({ account: systemUserSchema, delivery: passwordDeliverySchema })
  .meta({ id: 'CreateAccountResponse' });
export type CreateAccountResponse = z.infer<typeof createAccountResponseSchema>;

/** PATCH /system/users/:userId: corrections. A new officer name starts a new officer term. */
export const updateAccountRequestSchema = z
  .strictObject({
    email: accountEmailSchema,
    officerInCharge: officerInChargeInputSchema,
    termEnd: z.iso.date().nullable(),
  })
  .partial()
  .refine((patch) => Object.keys(patch).length > 0, 'Change at least one field');
export type UpdateAccountRequest = z.infer<typeof updateAccountRequestSchema>;

/** PATCH /system/users/:userId/lock: a temporary hold. Locking needs a reason. */
export const setLockRequestSchema = z
  .strictObject({
    locked: z.boolean(),
    reason: z.string().trim().min(3, 'Say why, in a few words').max(200).optional(),
  })
  .refine((body) => !body.locked || body.reason !== undefined, {
    path: ['reason'],
    message: 'Say why, in a few words',
  });
export type SetLockRequest = z.infer<typeof setLockRequestSchema>;

/** POST /system/users/:userId/password-reset */
export const passwordResetResponseSchema = z
  .object({ account: systemUserSchema, delivery: passwordDeliverySchema })
  .meta({ id: 'PasswordResetResponse' });
export type PasswordResetResponse = z.infer<typeof passwordResetResponseSchema>;

/*
 * File support: the super admin sees an organization's file details without opening or
 * downloading them. A private file's title is hidden too (docs/DOMAIN_RULES.md, "Accounts").
 */

export const supportDocumentSchema = z
  .object({
    id: z.uuid(),
    /** Null for a private file: not even its name is shown. */
    title: z.string().nullable(),
    type: z.string(),
    status: documentStatusSchema,
    visibility: documentVisibilitySchema,
    isTestData: z.boolean(),
    sizeBytes: z.number().int().nullable(),
    scanStatus: scanStatusSchema.nullable(),
    /** Still scanning 15 minutes after its last upload: a scan can be run again. */
    stuck: z.boolean(),
    createdAt: z.iso.datetime(),
    updatedAt: z.iso.datetime(),
  })
  .meta({ id: 'SupportDocument' });
export type SupportDocument = z.infer<typeof supportDocumentSchema>;

export const supportDocumentListSchema = z
  .object({
    organization: z.object({ slug: z.string(), acronym: z.string(), name: z.string() }),
    items: z.array(supportDocumentSchema),
  })
  .meta({ id: 'SupportDocumentList' });
export type SupportDocumentList = z.infer<typeof supportDocumentListSchema>;

/** GET /system/test-data: every file still flagged as test data, before deleting them. */
export const testDataPreviewSchema = z
  .object({
    total: z.number().int().min(0),
    items: z.array(
      z.object({
        id: z.uuid(),
        organization: z.object({ slug: z.string(), acronym: z.string() }),
        type: z.string(),
        status: documentStatusSchema,
        createdAt: z.iso.datetime(),
      }),
    ),
  })
  .meta({ id: 'TestDataPreview' });
export type TestDataPreview = z.infer<typeof testDataPreviewSchema>;

/**
 * POST /system/test-data/delete: soft-deletes every test-data file. `expectedCount` is the
 * total the preview showed; if it changed since, nothing is deleted (409) and the preview is
 * shown again.
 */
export const deleteTestDataRequestSchema = z.strictObject({
  expectedCount: z.number().int().min(1),
});
export type DeleteTestDataRequest = z.infer<typeof deleteTestDataRequestSchema>;

export const deleteTestDataResponseSchema = z
  .object({ deleted: z.number().int().min(0) })
  .meta({ id: 'DeleteTestDataResponse' });
export type DeleteTestDataResponse = z.infer<typeof deleteTestDataResponseSchema>;
